// Generated by design/build.ts from design/src/tokens.css and panel.css; edit those and run `bun run build`.

/** The panels' stylesheet: the tokens and panel.css, no webfonts. */
export const panelCss: string = "/*\n * Tempra design tokens: the one place values live (TEMPRA-8). Two tiers: the palette's\n * primitives (--tempra-white, --tempra-grey-warm-*, --tempra-grey-cool-*, --tempra-orange-* and\n * the chart hues), raw values that only this file reads, and the roles every stylesheet uses, each\n * named --tempra-<group>-<name>: color, focus, font, text (sizes), weight, leading, measure, space,\n * size, radius, motion, shadow. A colour role is light-dark() over two primitives. Take 2 of the\n * design (TEMPRA-53, design/handoff/layout-take-2) set structure and type: neutral greys, a type\n * scale, radii and one soft shadow. Take 3\n * (TEMPRA-106) set the frame's sizes and squarer corners, and take 4 (TEMPRA-113,\n * design/handoff/layout-take-4) the top bar, the wider sidebar and the panel. The one colour before\n * the palette is the agent's: the change dot that pulses while an agent writes, and its ink. The\n * palette (TEMPRA-1) changes values here and both the app and the site follow. Light and dark come\n * from the system through light-dark(), or from the account's theme on the root (data-theme).\n *\n * What stays literal in the CSS: 1px (hairlines, and the 1px between rows), 2px rules and\n * underlines (a quote's rule, the active comment), 50% for a circle, 0, unitless flex and grid\n * factors, em inside .prose (its rhythm scales with the reading size), and a component's own\n * one-off dimension, commented where it is used. Breakpoints too: a media or container query\n * cannot read a token.\n */\n:root {\n  color-scheme: light dark;\n\n  /* Palette: the primitives (TEMPRA-251), one tier below the colours. Raw values with\n     no role, each named by its family and its OKLCH lightness x1000, as the space scale is named by\n     its px: --tempra-grey-warm-964 is #f3f3f1 at L 0.964. Only the colour tokens below read them;\n     a stylesheet never does (design.test.ts), so a theme or the palette (TEMPRA-1) changes which\n     primitive a role points at, here, and nothing else. Two greys: warm (hue about 107) for the\n     light scheme's surfaces and lines, cool (hue 286) for ink and the dark scheme's surfaces. Each\n     value the colours used is kept exactly, near twins included (cool-287 and cool-286, cool-601\n     and cool-594); folding them into a ramp is the palette's call. */\n  --tempra-white: #ffffff;\n\n  /* Palette: warm greys */\n  --tempra-grey-warm-964: #f3f3f1;\n  --tempra-grey-warm-951: #efefeb;\n  --tempra-grey-warm-943: #ececea;\n  --tempra-grey-warm-933: #e9e9e6;\n  --tempra-grey-warm-930: #e8e8e4;\n  --tempra-grey-warm-909: #e1e1dd;\n  --tempra-grey-warm-899: #dededa;\n  --tempra-grey-warm-893: #dcdcd6;\n  --tempra-grey-warm-863: #d2d2ce;\n\n  /* Palette: cool greys */\n  --tempra-grey-cool-717: #a3a3a7;\n  --tempra-grey-cool-687: #9a9a9e;\n  --tempra-grey-cool-635: #8a8a8e;\n  --tempra-grey-cool-601: #808084;\n  --tempra-grey-cool-594: #7e7e82;\n  --tempra-grey-cool-519: #68686c;\n  --tempra-grey-cool-494: #616165;\n  --tempra-grey-cool-358: #3c3c40;\n  --tempra-grey-cool-350: #3a3a3d;\n  --tempra-grey-cool-342: #38383c;\n  --tempra-grey-cool-287: #2a2a2e;\n  --tempra-grey-cool-286: #2a2a2d;\n  --tempra-grey-cool-253: #222225;\n  --tempra-grey-cool-223: #1b1b1d;\n  --tempra-grey-cool-218: #1a1a1b;\n  --tempra-grey-cool-183: #121214;\n  --tempra-grey-cool-164: #0e0e0f;\n  --tempra-grey-cool-145: #0a0a0b;\n\n  /* Palette: orange, the agent's (and the chart's second series) */\n  --tempra-orange-728: #f0884a;\n  --tempra-orange-680: #e8722a;\n  --tempra-orange-671: #eb6834;\n  --tempra-orange-622: #d95926;\n  --tempra-orange-509: #9e4a1a;\n\n  /* Palette: the chart series' other hues (TEMPRA-217), a light and a dark step each */\n  --tempra-blue-622: #3987e5;\n  --tempra-blue-575: #2a78d6;\n  --tempra-aqua-669: #1baf7a;\n  --tempra-aqua-621: #199e70;\n  --tempra-yellow-764: #eda100;\n  --tempra-yellow-670: #c98500;\n  --tempra-magenta-716: #e87ba4;\n  --tempra-magenta-622: #d55181;\n  --tempra-green-529: #008300;\n  --tempra-violet-670: #9085e9;\n  --tempra-violet-527: #6250d6;\n  --tempra-red-669: #e66767;\n  --tempra-red-623: #e34948;\n\n  /* Color: surfaces */\n  --tempra-color-bg: light-dark(\n    var(--tempra-white),\n    var(--tempra-grey-cool-223)\n  ); /* the page, panels, pills */\n  --tempra-color-ground: light-dark(\n    var(--tempra-grey-warm-964),\n    var(--tempra-grey-cool-183)\n  ); /* the page under them, inset fills */\n  --tempra-color-hover: light-dark(var(--tempra-grey-warm-933), var(--tempra-grey-cool-253));\n  --tempra-color-selected: light-dark(var(--tempra-grey-warm-909), var(--tempra-grey-cool-287));\n  --tempra-color-selection: light-dark(var(--tempra-grey-warm-899), var(--tempra-grey-cool-350));\n\n  /* Color: text, in three steps. Text people read is text or muted, at least 4.5:1 on every\n     surface in light and dark (TEMPRA-132; design/contrast.test.ts). Faint is under that: icons,\n     rules and disabled controls only, never words. */\n  --tempra-color-text: light-dark(var(--tempra-grey-cool-218), var(--tempra-grey-warm-943));\n  --tempra-color-muted: light-dark(var(--tempra-grey-cool-494), var(--tempra-grey-cool-687));\n  --tempra-color-faint: light-dark(var(--tempra-grey-cool-717), var(--tempra-grey-cool-519));\n\n  /* Color: lines */\n  --tempra-color-border: light-dark(var(--tempra-grey-warm-930), var(--tempra-grey-cool-286));\n  --tempra-color-border-strong: light-dark(\n    var(--tempra-grey-warm-863),\n    var(--tempra-grey-cool-358)\n  );\n\n  /* Focus (TEMPRA-132): a 2px ring in the text colour on every control focused by keyboard\n     (:focus-visible), until the palette (TEMPRA-1) designs its own. A field's ring sits closer. */\n  --tempra-focus-ring: 2px solid var(--tempra-color-text);\n  --tempra-focus-offset: 2px;\n  --tempra-focus-offset-field: 1px;\n\n  /* Color: the agent's (the only colour before the palette): the change dot, pulsing while an\n     agent writes now (take 4), and Tempra's own agent's round mark */\n  --tempra-color-agent: light-dark(var(--tempra-orange-680), var(--tempra-orange-728));\n  /* The same colour deep enough to sit in words (TEMPRA-219): the highlight that moves across\n     the name of a file an agent is at now, and its static mark under reduced motion. At least\n     4.5:1 on every surface, as text is (design/contrast.test.ts). */\n  --tempra-color-agent-ink: light-dark(var(--tempra-orange-509), var(--tempra-orange-728));\n  /* A letter on the agent colour: Tempra's own agent's round mark (TEMPRA-223). Dark in both\n     schemes, at least 4.5:1 on the colour (design/contrast.test.ts). */\n  --tempra-color-on-agent: light-dark(var(--tempra-grey-cool-218), var(--tempra-grey-cool-218));\n\n  /* Color: commented text in a concept's body (TEMPRA-223), greys only: an open thread's quote on\n     a soft fill over a solid mid-grey underline, the thread in focus on a deeper fill with an ink\n     underline. Text keeps at least 4.5:1 on both fills, and the underline 3:1 on the soft fill\n     and the page (design/contrast.test.ts). */\n  --tempra-color-comment: light-dark(var(--tempra-grey-warm-951), var(--tempra-grey-cool-287));\n  --tempra-color-comment-active: light-dark(\n    var(--tempra-grey-warm-893),\n    var(--tempra-grey-cool-342)\n  );\n  --tempra-color-comment-line: light-dark(var(--tempra-grey-cool-594), var(--tempra-grey-cool-601));\n\n  /* Color: chart series (TEMPRA-217). The agreed exception to \"no colour until the palette\"\n     besides the agent's, for a Vega-Lite chart's series and categories only: greys cannot tell\n     two lines apart. Axes, grid and text stay grey. Eight hues in a fixed order, each stepped for\n     its scheme, checked against the page (--tempra-color-bg) with the dataviz validator: adjacent\n     pairs apart under protanopia and deuteranopia, every pair apart to normal vision; three light\n     steps sit under 3:1 on white, so a chart keeps its legend (design/contrast.test.ts). The\n     palette (TEMPRA-1) may replace them. */\n  --tempra-color-chart-1: light-dark(var(--tempra-blue-575), var(--tempra-blue-622)); /* blue */\n  --tempra-color-chart-2: light-dark(\n    var(--tempra-orange-671),\n    var(--tempra-orange-622)\n  ); /* orange */\n  --tempra-color-chart-3: light-dark(var(--tempra-aqua-669), var(--tempra-aqua-621)); /* aqua */\n  --tempra-color-chart-4: light-dark(\n    var(--tempra-yellow-764),\n    var(--tempra-yellow-670)\n  ); /* yellow */\n  --tempra-color-chart-5: light-dark(\n    var(--tempra-magenta-716),\n    var(--tempra-magenta-622)\n  ); /* magenta */\n  --tempra-color-chart-6: light-dark(var(--tempra-green-529), var(--tempra-green-529)); /* green */\n  --tempra-color-chart-7: light-dark(\n    var(--tempra-violet-527),\n    var(--tempra-violet-670)\n  ); /* violet */\n  --tempra-color-chart-8: light-dark(var(--tempra-red-623), var(--tempra-red-669)); /* red */\n\n  /* Color: a dimmed page behind an overlaid panel, the phone's drawer or sheet, or a dialog */\n  --tempra-color-scrim: light-dark(rgb(20 20 22 / 0.2), rgb(0 0 0 / 0.5));\n\n  /* Color: the dark frame an attachment is shown on (take 4, board 28), and a mark on it */\n  --tempra-color-frame: light-dark(var(--tempra-grey-cool-164), var(--tempra-grey-cool-145));\n  --tempra-color-frame-ink: light-dark(var(--tempra-grey-cool-635), var(--tempra-grey-cool-635));\n\n  /* Color: links are text, underlined in running text (no colour until the palette) */\n  --tempra-color-link: var(--tempra-color-text);\n  --tempra-color-link-visited: var(--tempra-color-text);\n  --tempra-color-code-bg: var(--tempra-color-ground);\n\n  /* Elevation */\n  --tempra-shadow:\n    0 1px 2px light-dark(rgb(0 0 0 / 0.04), rgb(0 0 0 / 0.4)),\n    0 6px 24px light-dark(rgb(0 0 0 / 0.04), rgb(0 0 0 / 0.35));\n\n  /* Type (TEMPRA-108; Inter since 2026-10-23, tempra-dev decisions/one-face.md): one family, Inter\n     (fonts.css), in two roles, and the mono for code. The variable font's optical-size axis is the\n     pairing: the display cut for titles, the text cut for everything read at reading sizes.\n     display: titles and large headings (h1, a view's title, a page's title, the body's h1 and h2,\n       an attachment's name, a compose dialog's name), at the display optical size.\n     text: everything else (chrome, labels, the byline, a page's body, comments, public pages).\n     mono: code, fences, the Markdown view, paths and hashes.\n     The system faces after Inter cover what it has no glyphs for. */\n  --tempra-font-text:\n    \"Inter\", -apple-system, BlinkMacSystemFont, system-ui, \"Segoe UI\", Helvetica, sans-serif;\n  --tempra-font-display: var(--tempra-font-text);\n  --tempra-font-display-settings: \"opsz\" 32; /* Inter's display cut, at any size it is used */\n  --tempra-font-mono: ui-monospace, \"SF Mono\", Menlo, monospace;\n\n  /* Type scale: the only pixel sizes in the CSS (inside .prose, sizes are em of the reading size) */\n  --tempra-text-initial: 9px; /* an avatar's initials */\n  --tempra-text-label: 11px; /* uppercase labels, marks */\n  --tempra-text-meta: 12px; /* timestamps, small print */\n  --tempra-text-ui: 13px; /* controls, panels, the tree, comments */\n  --tempra-text-base: 14px; /* the app's base text */\n  --tempra-text-name: 15px; /* a library's name, dialog heads, the wordmark */\n  --tempra-text-reader: 17px; /* a concept's body and description, the landing page's lede */\n  --tempra-text-h2: 22px; /* an attachment's name, a compose dialog's name */\n  --tempra-text-page: 28px; /* a view's title (h1); a concept's title on a phone */\n  --tempra-text-title: 36px; /* a concept's title */\n  --tempra-text-code: 0.92em; /* code, a step under the text around it */\n\n  /* Weights: three */\n  --tempra-weight-regular: 400; /* text */\n  --tempra-weight-medium: 500; /* names in rows, a concept's title, the body's h1 and h2 */\n  --tempra-weight-strong: 600; /* the sans's headings, section labels, the wordmark */\n\n  /* Leading: three */\n  --tempra-leading-tight: 1.2; /* titles and headings */\n  --tempra-leading-base: 1.5; /* the app's text */\n  --tempra-leading-reader: 1.65; /* reading */\n\n  /* Tracking */\n  --tempra-tracking-label: 0.04em; /* uppercase labels */\n  --tempra-tracking-title: -0.02em; /* h1 and a view's title */\n  --tempra-tracking-doc: -0.01em; /* a concept's title */\n\n  /* Lines: a link's underline sits this far under the text (inside .prose, in em) */\n  --tempra-line-offset: 2px;\n\n  /* Measure */\n  --tempra-measure: 680px; /* the reader's column, with its padding: diagrams, captions */\n  --tempra-measure-reader: 34em; /* concept text: about 66 characters at the reading size */\n\n  /* Space: one scale in rem, so spacing grows with the reader's chosen text size, named by its\n     size in px at the default 16px root (take 2 to take 4 used every step below; the palette\n     round may thin it). Only these appear as padding, margin, gap and offsets. */\n  --tempra-space-02: 0.125rem;\n  --tempra-space-04: 0.25rem;\n  --tempra-space-06: 0.375rem;\n  --tempra-space-08: 0.5rem;\n  --tempra-space-10: 0.625rem;\n  --tempra-space-12: 0.75rem;\n  --tempra-space-14: 0.875rem;\n  --tempra-space-16: 1rem;\n  --tempra-space-18: 1.125rem;\n  --tempra-space-20: 1.25rem;\n  --tempra-space-24: 1.5rem;\n  --tempra-space-28: 1.75rem;\n  --tempra-space-32: 2rem;\n  --tempra-space-40: 2.5rem;\n  --tempra-space-48: 3rem;\n  --tempra-space-56: 3.5rem;\n  --tempra-space-72: 4.5rem;\n  --tempra-space-96: 6rem;\n  --tempra-space-gutter: var(--tempra-space-08); /* the frame's gutter */\n  --tempra-space-page: var(--tempra-space-40); /* a page's side padding in its column */\n  --tempra-space-figure: var(--tempra-space-12); /* between a group's images */\n  /* Inside a control: a button's, a field's and a chip's padding (their 1px border makes up the\n     rest of a 30px pill at the UI size) */\n  --tempra-space-button: 5px 12px;\n  --tempra-space-field: 5px 10px;\n  --tempra-space-chip: 1px 7px;\n\n  /* Size: the frame (take 4): a top bar across the window, the sidebar, one panel beside a\n     concept. The breakpoints are 1100px (the panel overlays the page) and 900px (the phone\n     layout); a media query cannot read a token, so they are written where they are used. */\n  --tempra-size-topbar: 60px; /* the top bar */\n  --tempra-size-topbar-phone: 52px; /* the phone's top bar */\n  --tempra-size-sidebar: 264px; /* the sidebar's width */\n  --tempra-size-panel: 360px; /* a concept's panel (Comments, History, Properties) */\n  --tempra-size-panel-head: 56px; /* a panel's head; the phone sheet's is taller */\n  --tempra-size-panel-head-phone: 64px;\n  --tempra-size-drawer: min(82vw, 360px); /* the phone's drawer: about four fifths of the screen */\n  --tempra-size-sheet: 67dvh; /* a panel as the phone's bottom sheet: about two thirds of the screen */\n  --tempra-size-row: 30px; /* a sidebar row */\n  --tempra-size-touch: 44px; /* the least touch target on a phone */\n\n  /* Size: a concept's columns (take 4): the text, centred; on the right its contents, or a panel */\n  --tempra-size-column-text: 620px;\n  --tempra-size-contents: 200px;\n  --tempra-size-figure-wide: 960px; /* a wide figure (`layout=wide`), past the text's measure */\n  --tempra-size-page: 760px; /* home, Activity, Settings, the account's pages */\n  --tempra-size-page-wide: 960px; /* a page column that holds a table (the account's Agents) */\n\n  /* Size: controls and marks */\n  --tempra-size-control: 36px; /* the top bar's round buttons and pills */\n  --tempra-size-control-small: 30px; /* a round icon button elsewhere */\n  --tempra-size-control-mini: 24px; /* a figure's corner tools, a comment mark */\n  --tempra-size-icon: 16px; /* a glyph's box: the tree's chevron and file icon */\n  --tempra-size-icon-small: 12px; /* the tree's chevron itself */\n  --tempra-size-avatar: 22px; /* someone's round mark */\n  --tempra-size-avatar-small: 20px; /* in a compact thread */\n  --tempra-size-avatar-menu: 26px; /* the avatar button that opens the account menu */\n  --tempra-size-avatar-large: 32px; /* at the head of the account menu */\n  --tempra-size-tile: 24px; /* a library's initial */\n  --tempra-size-tile-small: 20px; /* in a row: the sidebar, a menu, the bell */\n  --tempra-size-tile-large: 28px; /* the Tempra mark, a library card's cover */\n  --tempra-size-badge: 16px; /* the bell's count */\n  --tempra-size-dot: 6px; /* an agent's change, the agent replying */\n  --tempra-size-fab: 56px; /* a page's actions, floating */\n\n  /* Size: cards and dialogs */\n  --tempra-size-dialog: 32rem;\n  --tempra-size-dialog-wide: 40rem; /* a wide or compose dialog */\n  --tempra-size-media: 32rem; /* audio, a PDF's card and a broken figure in the full-screen view and on an attachment's page */\n  --tempra-size-menu: 13rem; /* a menu's least width */\n  --tempra-size-popover: 360px; /* the bell's panel */\n  --tempra-size-card: 240px; /* a library card's least width, the page's actions menu */\n  --tempra-size-tooltip: 22rem; /* a hover card */\n  --tempra-size-field: 22rem; /* a form field's widest */\n\n  /* Shape: squarer than take 2 */\n  --tempra-radius-code: 5px; /* code */\n  --tempra-radius-row: 7px; /* sidebar rows, inputs */\n  --tempra-radius-box: 10px; /* cards, list boxes, threads */\n  --tempra-radius-card: 10px; /* the public pages' sheet, dialogs */\n  --tempra-radius-tile: 6px; /* the library's initial */\n  --tempra-radius-pill: 999px;\n\n  /* Motion */\n  --tempra-motion-quick: 0.15s; /* a chevron or a + turning */\n  --tempra-motion-pulse: 1.6s; /* the change dot's pulse while an agent writes */\n  --tempra-motion-shimmer: 2s; /* one pass of the shimmer over a name an agent is at now (TEMPRA-219) */\n}\n\n/* The account's theme (take 4): the shell puts it on the root; the tokens above follow. */\n:root[data-theme=\"light\"] {\n  color-scheme: light;\n}\n\n:root[data-theme=\"dark\"] {\n  color-scheme: dark;\n}\n\n/*\n * Panels: the views an MCP host draws in a chat (TEMPRA-200, the upload panel; tempra-dev\n * app/media, Upload panel). Not part of tempra.css: build.ts puts tokens.css and this file into\n * dist/panel.ts, which the app's build inlines into each panel's one HTML document. A panel sits\n * in the host's conversation, so it takes the host's theme variables (SEP-1865, Theming) where\n * the host gives them, and Tempra's greys where it does not. No webfont: the host's sans, else\n * the system's.\n */\n\n:root {\n  color-scheme: light dark;\n}\n\n:root[data-theme=\"light\"] {\n  color-scheme: light;\n}\n\n:root[data-theme=\"dark\"] {\n  color-scheme: dark;\n}\n\n.panel {\n  --panel-text: var(--color-text-primary, var(--tempra-color-text));\n  --panel-muted: var(--color-text-secondary, var(--tempra-color-muted));\n  --panel-surface: var(--color-background-primary, var(--tempra-color-bg));\n  --panel-inset: var(--color-background-secondary, var(--tempra-color-ground));\n  --panel-border: var(--color-border-primary, var(--tempra-color-border-strong));\n  --panel-radius: var(--border-radius-lg, var(--tempra-radius-box));\n  margin: 0;\n  padding: var(--tempra-space-16);\n  background: var(--panel-surface);\n  color: var(--panel-text);\n  font-family: var(--font-sans, system-ui, -apple-system, \"Segoe UI\", sans-serif);\n  font-size: var(--tempra-text-base);\n  line-height: 1.45; /* the hosts' own leading, a little tighter than the app's */\n}\n\n.panel h1 {\n  margin: 0 0 var(--tempra-space-04);\n  font-size: var(--tempra-text-name);\n  font-weight: var(--tempra-weight-strong);\n}\n\n.panel p {\n  margin: 0 0 var(--tempra-space-08);\n}\n\n.panel .muted {\n  color: var(--panel-muted);\n}\n\n.panel code {\n  font-family: var(--font-mono, ui-monospace, \"SF Mono\", Menlo, monospace);\n  font-size: var(--tempra-text-code);\n  overflow-wrap: anywhere;\n}\n\n/* The drop area: the file input's label, a dashed box that says what to do. */\n.panel .drop {\n  display: block;\n  margin: var(--tempra-space-12) 0 var(--tempra-space-08);\n  padding: var(--tempra-space-20) var(--tempra-space-16);\n  border: 1.5px dashed var(--panel-border); /* one-off: the drop area's edge */\n  border-radius: var(--panel-radius);\n  background: var(--panel-inset);\n  text-align: center;\n  cursor: pointer;\n}\n\n/* Gone once the file is in: `hidden` over the display rule above. */\n.panel .drop[hidden] {\n  display: none;\n}\n\n.panel .drop .hint {\n  display: block;\n  margin-top: var(--tempra-space-04);\n}\n\n.panel .drop.over {\n  border-style: solid;\n  border-color: var(--panel-text);\n}\n\n.panel .drop:focus-within {\n  outline: 2px solid var(--panel-text); /* the focus ring, in the host's text colour */\n  outline-offset: var(--tempra-focus-offset);\n}\n\n/* The input stays in the label for the keyboard and screen readers, out of sight. */\n.panel .drop input {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\n.panel .status {\n  min-height: 1.45em;\n  margin: var(--tempra-space-08) 0 0;\n}\n\n.panel .actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: var(--tempra-space-08);\n  align-items: center;\n  margin-top: var(--tempra-space-08);\n}\n\n.panel button {\n  padding: var(--tempra-space-06) var(--tempra-space-14);\n  border: 1px solid var(--panel-border);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--panel-surface);\n  color: var(--panel-text);\n  font: inherit;\n  cursor: pointer;\n}\n\n.panel button.primary {\n  border-color: var(--panel-text);\n  background: var(--panel-text);\n  color: var(--panel-surface);\n}\n\n.panel button:disabled {\n  cursor: default;\n}\n\n.panel button:focus-visible {\n  outline: 2px solid var(--panel-text); /* the focus ring, in the host's text colour */\n  outline-offset: var(--tempra-focus-offset);\n}\n\n.panel progress {\n  width: 100%;\n  height: 6px; /* one-off: the progress bar */\n  margin-top: var(--tempra-space-08);\n}\n\n/* ---------- The page panel (tempra-dev app/page-panel): one page shown in the chat by `show` ----------\n * Unlike the upload panel it reads as Tempra does, not as the host: Inter, the reader's prose and\n * the base pills. Its stylesheet is fonts, tokens, base, prose, reader and this file (build.ts,\n * dist/panel.ts `pagePanelCss`); the host's light or dark comes in as data-theme. */\n\n.page-body {\n  margin: 0;\n  padding: var(--tempra-space-20) var(--tempra-space-20) var(--tempra-space-24);\n  background: var(--tempra-color-bg);\n}\n\n.page-panel .pp-head {\n  margin-bottom: var(--tempra-space-24);\n}\n\n.page-panel .pp-where {\n  margin: 0 0 var(--tempra-space-12);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.page-panel .pp-title {\n  margin: 0 0 var(--tempra-space-08);\n  font-family: var(--tempra-font-display);\n  font-variation-settings: var(--tempra-font-display-settings);\n  font-size: var(--tempra-text-page);\n  font-weight: var(--tempra-weight-medium);\n  line-height: var(--tempra-leading-tight);\n  letter-spacing: var(--tempra-tracking-doc);\n}\n\n.page-panel .pp-description {\n  margin: 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-reader);\n}\n\n.page-panel .pp-byline {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--tempra-space-06) var(--tempra-space-08);\n  margin: var(--tempra-space-12) 0 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.page-panel .prose {\n  max-width: var(--tempra-measure-reader);\n}\n\n.page-panel .pp-sources {\n  margin-top: 2em;\n  padding-top: 1em;\n  border-top: 1px solid var(--tempra-color-border);\n}\n\n.page-panel .pp-sources h2 {\n  margin-top: 0;\n}\n";

/** The page panel's stylesheet: Inter at `/_design/` names, tokens, base, prose, reader, panel. */
export const pagePanelCss: string = "/*\n * Inter (rsms.me/inter, SIL Open Font License 1.1, design/fonts/OFL.txt), self-hosted: the\n * variable font with weight and optical-size axes, so one family gives the display cut at large\n * sizes and the text cut at reading sizes (tempra-dev decisions/one-face.md). From\n * @fontsource-variable/inter 5.3.0, split by script; a browser fetches only the subsets a page\n * uses (unicode-range). The app's build points the URLs at hashed copies the Worker serves.\n */\n\n@font-face {\n  font-family: \"Inter\";\n  font-style: normal;\n  font-weight: 100 900;\n  font-display: swap;\n  src: url(\"/_design/inter-cyrillic-ext-opsz-normal.e3a8d2d7497a.woff2\") format(\"woff2\");\n  unicode-range: U+0460-052F, U+1C80-1C8A, U+20B4, U+2DE0-2DFF, U+A640-A69F, U+FE2E-FE2F;\n}\n\n@font-face {\n  font-family: \"Inter\";\n  font-style: normal;\n  font-weight: 100 900;\n  font-display: swap;\n  src: url(\"/_design/inter-cyrillic-opsz-normal.e1dea13a93c6.woff2\") format(\"woff2\");\n  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;\n}\n\n@font-face {\n  font-family: \"Inter\";\n  font-style: normal;\n  font-weight: 100 900;\n  font-display: swap;\n  src: url(\"/_design/inter-greek-ext-opsz-normal.e0f32d9ee75a.woff2\") format(\"woff2\");\n  unicode-range: U+1F00-1FFF;\n}\n\n@font-face {\n  font-family: \"Inter\";\n  font-style: normal;\n  font-weight: 100 900;\n  font-display: swap;\n  src: url(\"/_design/inter-greek-opsz-normal.93c5ac80e25c.woff2\") format(\"woff2\");\n  unicode-range: U+0370-0377, U+037A-037F, U+0384-038A, U+038C, U+038E-03A1, U+03A3-03FF;\n}\n\n@font-face {\n  font-family: \"Inter\";\n  font-style: normal;\n  font-weight: 100 900;\n  font-display: swap;\n  src: url(\"/_design/inter-vietnamese-opsz-normal.935ab355938e.woff2\") format(\"woff2\");\n  unicode-range:\n    U+0102-0103, U+0110-0111, U+0128-0129, U+0168-0169, U+01A0-01A1, U+01AF-01B0, U+0300-0301, U+0303-0304, U+0308-0309, U+0323, U+0329, U+1EA0-1EF9, U+20AB;\n}\n\n@font-face {\n  font-family: \"Inter\";\n  font-style: normal;\n  font-weight: 100 900;\n  font-display: swap;\n  src: url(\"/_design/inter-latin-ext-opsz-normal.5e6d4fe9d9f4.woff2\") format(\"woff2\");\n  unicode-range:\n    U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF;\n}\n\n@font-face {\n  font-family: \"Inter\";\n  font-style: normal;\n  font-weight: 100 900;\n  font-display: swap;\n  src: url(\"/_design/inter-latin-opsz-normal.2c295d99e26d.woff2\") format(\"woff2\");\n  unicode-range:\n    U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;\n}\n\n@font-face {\n  font-family: \"Inter\";\n  font-style: italic;\n  font-weight: 100 900;\n  font-display: swap;\n  src: url(\"/_design/inter-cyrillic-ext-opsz-italic.4ee1c3b9f5a9.woff2\") format(\"woff2\");\n  unicode-range: U+0460-052F, U+1C80-1C8A, U+20B4, U+2DE0-2DFF, U+A640-A69F, U+FE2E-FE2F;\n}\n\n@font-face {\n  font-family: \"Inter\";\n  font-style: italic;\n  font-weight: 100 900;\n  font-display: swap;\n  src: url(\"/_design/inter-cyrillic-opsz-italic.cd3d9beabd6f.woff2\") format(\"woff2\");\n  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;\n}\n\n@font-face {\n  font-family: \"Inter\";\n  font-style: italic;\n  font-weight: 100 900;\n  font-display: swap;\n  src: url(\"/_design/inter-greek-ext-opsz-italic.f21ed36275ab.woff2\") format(\"woff2\");\n  unicode-range: U+1F00-1FFF;\n}\n\n@font-face {\n  font-family: \"Inter\";\n  font-style: italic;\n  font-weight: 100 900;\n  font-display: swap;\n  src: url(\"/_design/inter-greek-opsz-italic.94fd1ce2533a.woff2\") format(\"woff2\");\n  unicode-range: U+0370-0377, U+037A-037F, U+0384-038A, U+038C, U+038E-03A1, U+03A3-03FF;\n}\n\n@font-face {\n  font-family: \"Inter\";\n  font-style: italic;\n  font-weight: 100 900;\n  font-display: swap;\n  src: url(\"/_design/inter-vietnamese-opsz-italic.d102ea2c86a5.woff2\") format(\"woff2\");\n  unicode-range:\n    U+0102-0103, U+0110-0111, U+0128-0129, U+0168-0169, U+01A0-01A1, U+01AF-01B0, U+0300-0301, U+0303-0304, U+0308-0309, U+0323, U+0329, U+1EA0-1EF9, U+20AB;\n}\n\n@font-face {\n  font-family: \"Inter\";\n  font-style: italic;\n  font-weight: 100 900;\n  font-display: swap;\n  src: url(\"/_design/inter-latin-ext-opsz-italic.cd92c8740f77.woff2\") format(\"woff2\");\n  unicode-range:\n    U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF;\n}\n\n@font-face {\n  font-family: \"Inter\";\n  font-style: italic;\n  font-weight: 100 900;\n  font-display: swap;\n  src: url(\"/_design/inter-latin-opsz-italic.c58f9d530baa.woff2\") format(\"woff2\");\n  unicode-range:\n    U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;\n}\n\n/*\n * Tempra design tokens: the one place values live (TEMPRA-8). Two tiers: the palette's\n * primitives (--tempra-white, --tempra-grey-warm-*, --tempra-grey-cool-*, --tempra-orange-* and\n * the chart hues), raw values that only this file reads, and the roles every stylesheet uses, each\n * named --tempra-<group>-<name>: color, focus, font, text (sizes), weight, leading, measure, space,\n * size, radius, motion, shadow. A colour role is light-dark() over two primitives. Take 2 of the\n * design (TEMPRA-53, design/handoff/layout-take-2) set structure and type: neutral greys, a type\n * scale, radii and one soft shadow. Take 3\n * (TEMPRA-106) set the frame's sizes and squarer corners, and take 4 (TEMPRA-113,\n * design/handoff/layout-take-4) the top bar, the wider sidebar and the panel. The one colour before\n * the palette is the agent's: the change dot that pulses while an agent writes, and its ink. The\n * palette (TEMPRA-1) changes values here and both the app and the site follow. Light and dark come\n * from the system through light-dark(), or from the account's theme on the root (data-theme).\n *\n * What stays literal in the CSS: 1px (hairlines, and the 1px between rows), 2px rules and\n * underlines (a quote's rule, the active comment), 50% for a circle, 0, unitless flex and grid\n * factors, em inside .prose (its rhythm scales with the reading size), and a component's own\n * one-off dimension, commented where it is used. Breakpoints too: a media or container query\n * cannot read a token.\n */\n:root {\n  color-scheme: light dark;\n\n  /* Palette: the primitives (TEMPRA-251), one tier below the colours. Raw values with\n     no role, each named by its family and its OKLCH lightness x1000, as the space scale is named by\n     its px: --tempra-grey-warm-964 is #f3f3f1 at L 0.964. Only the colour tokens below read them;\n     a stylesheet never does (design.test.ts), so a theme or the palette (TEMPRA-1) changes which\n     primitive a role points at, here, and nothing else. Two greys: warm (hue about 107) for the\n     light scheme's surfaces and lines, cool (hue 286) for ink and the dark scheme's surfaces. Each\n     value the colours used is kept exactly, near twins included (cool-287 and cool-286, cool-601\n     and cool-594); folding them into a ramp is the palette's call. */\n  --tempra-white: #ffffff;\n\n  /* Palette: warm greys */\n  --tempra-grey-warm-964: #f3f3f1;\n  --tempra-grey-warm-951: #efefeb;\n  --tempra-grey-warm-943: #ececea;\n  --tempra-grey-warm-933: #e9e9e6;\n  --tempra-grey-warm-930: #e8e8e4;\n  --tempra-grey-warm-909: #e1e1dd;\n  --tempra-grey-warm-899: #dededa;\n  --tempra-grey-warm-893: #dcdcd6;\n  --tempra-grey-warm-863: #d2d2ce;\n\n  /* Palette: cool greys */\n  --tempra-grey-cool-717: #a3a3a7;\n  --tempra-grey-cool-687: #9a9a9e;\n  --tempra-grey-cool-635: #8a8a8e;\n  --tempra-grey-cool-601: #808084;\n  --tempra-grey-cool-594: #7e7e82;\n  --tempra-grey-cool-519: #68686c;\n  --tempra-grey-cool-494: #616165;\n  --tempra-grey-cool-358: #3c3c40;\n  --tempra-grey-cool-350: #3a3a3d;\n  --tempra-grey-cool-342: #38383c;\n  --tempra-grey-cool-287: #2a2a2e;\n  --tempra-grey-cool-286: #2a2a2d;\n  --tempra-grey-cool-253: #222225;\n  --tempra-grey-cool-223: #1b1b1d;\n  --tempra-grey-cool-218: #1a1a1b;\n  --tempra-grey-cool-183: #121214;\n  --tempra-grey-cool-164: #0e0e0f;\n  --tempra-grey-cool-145: #0a0a0b;\n\n  /* Palette: orange, the agent's (and the chart's second series) */\n  --tempra-orange-728: #f0884a;\n  --tempra-orange-680: #e8722a;\n  --tempra-orange-671: #eb6834;\n  --tempra-orange-622: #d95926;\n  --tempra-orange-509: #9e4a1a;\n\n  /* Palette: the chart series' other hues (TEMPRA-217), a light and a dark step each */\n  --tempra-blue-622: #3987e5;\n  --tempra-blue-575: #2a78d6;\n  --tempra-aqua-669: #1baf7a;\n  --tempra-aqua-621: #199e70;\n  --tempra-yellow-764: #eda100;\n  --tempra-yellow-670: #c98500;\n  --tempra-magenta-716: #e87ba4;\n  --tempra-magenta-622: #d55181;\n  --tempra-green-529: #008300;\n  --tempra-violet-670: #9085e9;\n  --tempra-violet-527: #6250d6;\n  --tempra-red-669: #e66767;\n  --tempra-red-623: #e34948;\n\n  /* Color: surfaces */\n  --tempra-color-bg: light-dark(\n    var(--tempra-white),\n    var(--tempra-grey-cool-223)\n  ); /* the page, panels, pills */\n  --tempra-color-ground: light-dark(\n    var(--tempra-grey-warm-964),\n    var(--tempra-grey-cool-183)\n  ); /* the page under them, inset fills */\n  --tempra-color-hover: light-dark(var(--tempra-grey-warm-933), var(--tempra-grey-cool-253));\n  --tempra-color-selected: light-dark(var(--tempra-grey-warm-909), var(--tempra-grey-cool-287));\n  --tempra-color-selection: light-dark(var(--tempra-grey-warm-899), var(--tempra-grey-cool-350));\n\n  /* Color: text, in three steps. Text people read is text or muted, at least 4.5:1 on every\n     surface in light and dark (TEMPRA-132; design/contrast.test.ts). Faint is under that: icons,\n     rules and disabled controls only, never words. */\n  --tempra-color-text: light-dark(var(--tempra-grey-cool-218), var(--tempra-grey-warm-943));\n  --tempra-color-muted: light-dark(var(--tempra-grey-cool-494), var(--tempra-grey-cool-687));\n  --tempra-color-faint: light-dark(var(--tempra-grey-cool-717), var(--tempra-grey-cool-519));\n\n  /* Color: lines */\n  --tempra-color-border: light-dark(var(--tempra-grey-warm-930), var(--tempra-grey-cool-286));\n  --tempra-color-border-strong: light-dark(\n    var(--tempra-grey-warm-863),\n    var(--tempra-grey-cool-358)\n  );\n\n  /* Focus (TEMPRA-132): a 2px ring in the text colour on every control focused by keyboard\n     (:focus-visible), until the palette (TEMPRA-1) designs its own. A field's ring sits closer. */\n  --tempra-focus-ring: 2px solid var(--tempra-color-text);\n  --tempra-focus-offset: 2px;\n  --tempra-focus-offset-field: 1px;\n\n  /* Color: the agent's (the only colour before the palette): the change dot, pulsing while an\n     agent writes now (take 4), and Tempra's own agent's round mark */\n  --tempra-color-agent: light-dark(var(--tempra-orange-680), var(--tempra-orange-728));\n  /* The same colour deep enough to sit in words (TEMPRA-219): the highlight that moves across\n     the name of a file an agent is at now, and its static mark under reduced motion. At least\n     4.5:1 on every surface, as text is (design/contrast.test.ts). */\n  --tempra-color-agent-ink: light-dark(var(--tempra-orange-509), var(--tempra-orange-728));\n  /* A letter on the agent colour: Tempra's own agent's round mark (TEMPRA-223). Dark in both\n     schemes, at least 4.5:1 on the colour (design/contrast.test.ts). */\n  --tempra-color-on-agent: light-dark(var(--tempra-grey-cool-218), var(--tempra-grey-cool-218));\n\n  /* Color: commented text in a concept's body (TEMPRA-223), greys only: an open thread's quote on\n     a soft fill over a solid mid-grey underline, the thread in focus on a deeper fill with an ink\n     underline. Text keeps at least 4.5:1 on both fills, and the underline 3:1 on the soft fill\n     and the page (design/contrast.test.ts). */\n  --tempra-color-comment: light-dark(var(--tempra-grey-warm-951), var(--tempra-grey-cool-287));\n  --tempra-color-comment-active: light-dark(\n    var(--tempra-grey-warm-893),\n    var(--tempra-grey-cool-342)\n  );\n  --tempra-color-comment-line: light-dark(var(--tempra-grey-cool-594), var(--tempra-grey-cool-601));\n\n  /* Color: chart series (TEMPRA-217). The agreed exception to \"no colour until the palette\"\n     besides the agent's, for a Vega-Lite chart's series and categories only: greys cannot tell\n     two lines apart. Axes, grid and text stay grey. Eight hues in a fixed order, each stepped for\n     its scheme, checked against the page (--tempra-color-bg) with the dataviz validator: adjacent\n     pairs apart under protanopia and deuteranopia, every pair apart to normal vision; three light\n     steps sit under 3:1 on white, so a chart keeps its legend (design/contrast.test.ts). The\n     palette (TEMPRA-1) may replace them. */\n  --tempra-color-chart-1: light-dark(var(--tempra-blue-575), var(--tempra-blue-622)); /* blue */\n  --tempra-color-chart-2: light-dark(\n    var(--tempra-orange-671),\n    var(--tempra-orange-622)\n  ); /* orange */\n  --tempra-color-chart-3: light-dark(var(--tempra-aqua-669), var(--tempra-aqua-621)); /* aqua */\n  --tempra-color-chart-4: light-dark(\n    var(--tempra-yellow-764),\n    var(--tempra-yellow-670)\n  ); /* yellow */\n  --tempra-color-chart-5: light-dark(\n    var(--tempra-magenta-716),\n    var(--tempra-magenta-622)\n  ); /* magenta */\n  --tempra-color-chart-6: light-dark(var(--tempra-green-529), var(--tempra-green-529)); /* green */\n  --tempra-color-chart-7: light-dark(\n    var(--tempra-violet-527),\n    var(--tempra-violet-670)\n  ); /* violet */\n  --tempra-color-chart-8: light-dark(var(--tempra-red-623), var(--tempra-red-669)); /* red */\n\n  /* Color: a dimmed page behind an overlaid panel, the phone's drawer or sheet, or a dialog */\n  --tempra-color-scrim: light-dark(rgb(20 20 22 / 0.2), rgb(0 0 0 / 0.5));\n\n  /* Color: the dark frame an attachment is shown on (take 4, board 28), and a mark on it */\n  --tempra-color-frame: light-dark(var(--tempra-grey-cool-164), var(--tempra-grey-cool-145));\n  --tempra-color-frame-ink: light-dark(var(--tempra-grey-cool-635), var(--tempra-grey-cool-635));\n\n  /* Color: links are text, underlined in running text (no colour until the palette) */\n  --tempra-color-link: var(--tempra-color-text);\n  --tempra-color-link-visited: var(--tempra-color-text);\n  --tempra-color-code-bg: var(--tempra-color-ground);\n\n  /* Elevation */\n  --tempra-shadow:\n    0 1px 2px light-dark(rgb(0 0 0 / 0.04), rgb(0 0 0 / 0.4)),\n    0 6px 24px light-dark(rgb(0 0 0 / 0.04), rgb(0 0 0 / 0.35));\n\n  /* Type (TEMPRA-108; Inter since 2026-10-23, tempra-dev decisions/one-face.md): one family, Inter\n     (fonts.css), in two roles, and the mono for code. The variable font's optical-size axis is the\n     pairing: the display cut for titles, the text cut for everything read at reading sizes.\n     display: titles and large headings (h1, a view's title, a page's title, the body's h1 and h2,\n       an attachment's name, a compose dialog's name), at the display optical size.\n     text: everything else (chrome, labels, the byline, a page's body, comments, public pages).\n     mono: code, fences, the Markdown view, paths and hashes.\n     The system faces after Inter cover what it has no glyphs for. */\n  --tempra-font-text:\n    \"Inter\", -apple-system, BlinkMacSystemFont, system-ui, \"Segoe UI\", Helvetica, sans-serif;\n  --tempra-font-display: var(--tempra-font-text);\n  --tempra-font-display-settings: \"opsz\" 32; /* Inter's display cut, at any size it is used */\n  --tempra-font-mono: ui-monospace, \"SF Mono\", Menlo, monospace;\n\n  /* Type scale: the only pixel sizes in the CSS (inside .prose, sizes are em of the reading size) */\n  --tempra-text-initial: 9px; /* an avatar's initials */\n  --tempra-text-label: 11px; /* uppercase labels, marks */\n  --tempra-text-meta: 12px; /* timestamps, small print */\n  --tempra-text-ui: 13px; /* controls, panels, the tree, comments */\n  --tempra-text-base: 14px; /* the app's base text */\n  --tempra-text-name: 15px; /* a library's name, dialog heads, the wordmark */\n  --tempra-text-reader: 17px; /* a concept's body and description, the landing page's lede */\n  --tempra-text-h2: 22px; /* an attachment's name, a compose dialog's name */\n  --tempra-text-page: 28px; /* a view's title (h1); a concept's title on a phone */\n  --tempra-text-title: 36px; /* a concept's title */\n  --tempra-text-code: 0.92em; /* code, a step under the text around it */\n\n  /* Weights: three */\n  --tempra-weight-regular: 400; /* text */\n  --tempra-weight-medium: 500; /* names in rows, a concept's title, the body's h1 and h2 */\n  --tempra-weight-strong: 600; /* the sans's headings, section labels, the wordmark */\n\n  /* Leading: three */\n  --tempra-leading-tight: 1.2; /* titles and headings */\n  --tempra-leading-base: 1.5; /* the app's text */\n  --tempra-leading-reader: 1.65; /* reading */\n\n  /* Tracking */\n  --tempra-tracking-label: 0.04em; /* uppercase labels */\n  --tempra-tracking-title: -0.02em; /* h1 and a view's title */\n  --tempra-tracking-doc: -0.01em; /* a concept's title */\n\n  /* Lines: a link's underline sits this far under the text (inside .prose, in em) */\n  --tempra-line-offset: 2px;\n\n  /* Measure */\n  --tempra-measure: 680px; /* the reader's column, with its padding: diagrams, captions */\n  --tempra-measure-reader: 34em; /* concept text: about 66 characters at the reading size */\n\n  /* Space: one scale in rem, so spacing grows with the reader's chosen text size, named by its\n     size in px at the default 16px root (take 2 to take 4 used every step below; the palette\n     round may thin it). Only these appear as padding, margin, gap and offsets. */\n  --tempra-space-02: 0.125rem;\n  --tempra-space-04: 0.25rem;\n  --tempra-space-06: 0.375rem;\n  --tempra-space-08: 0.5rem;\n  --tempra-space-10: 0.625rem;\n  --tempra-space-12: 0.75rem;\n  --tempra-space-14: 0.875rem;\n  --tempra-space-16: 1rem;\n  --tempra-space-18: 1.125rem;\n  --tempra-space-20: 1.25rem;\n  --tempra-space-24: 1.5rem;\n  --tempra-space-28: 1.75rem;\n  --tempra-space-32: 2rem;\n  --tempra-space-40: 2.5rem;\n  --tempra-space-48: 3rem;\n  --tempra-space-56: 3.5rem;\n  --tempra-space-72: 4.5rem;\n  --tempra-space-96: 6rem;\n  --tempra-space-gutter: var(--tempra-space-08); /* the frame's gutter */\n  --tempra-space-page: var(--tempra-space-40); /* a page's side padding in its column */\n  --tempra-space-figure: var(--tempra-space-12); /* between a group's images */\n  /* Inside a control: a button's, a field's and a chip's padding (their 1px border makes up the\n     rest of a 30px pill at the UI size) */\n  --tempra-space-button: 5px 12px;\n  --tempra-space-field: 5px 10px;\n  --tempra-space-chip: 1px 7px;\n\n  /* Size: the frame (take 4): a top bar across the window, the sidebar, one panel beside a\n     concept. The breakpoints are 1100px (the panel overlays the page) and 900px (the phone\n     layout); a media query cannot read a token, so they are written where they are used. */\n  --tempra-size-topbar: 60px; /* the top bar */\n  --tempra-size-topbar-phone: 52px; /* the phone's top bar */\n  --tempra-size-sidebar: 264px; /* the sidebar's width */\n  --tempra-size-panel: 360px; /* a concept's panel (Comments, History, Properties) */\n  --tempra-size-panel-head: 56px; /* a panel's head; the phone sheet's is taller */\n  --tempra-size-panel-head-phone: 64px;\n  --tempra-size-drawer: min(82vw, 360px); /* the phone's drawer: about four fifths of the screen */\n  --tempra-size-sheet: 67dvh; /* a panel as the phone's bottom sheet: about two thirds of the screen */\n  --tempra-size-row: 30px; /* a sidebar row */\n  --tempra-size-touch: 44px; /* the least touch target on a phone */\n\n  /* Size: a concept's columns (take 4): the text, centred; on the right its contents, or a panel */\n  --tempra-size-column-text: 620px;\n  --tempra-size-contents: 200px;\n  --tempra-size-figure-wide: 960px; /* a wide figure (`layout=wide`), past the text's measure */\n  --tempra-size-page: 760px; /* home, Activity, Settings, the account's pages */\n  --tempra-size-page-wide: 960px; /* a page column that holds a table (the account's Agents) */\n\n  /* Size: controls and marks */\n  --tempra-size-control: 36px; /* the top bar's round buttons and pills */\n  --tempra-size-control-small: 30px; /* a round icon button elsewhere */\n  --tempra-size-control-mini: 24px; /* a figure's corner tools, a comment mark */\n  --tempra-size-icon: 16px; /* a glyph's box: the tree's chevron and file icon */\n  --tempra-size-icon-small: 12px; /* the tree's chevron itself */\n  --tempra-size-avatar: 22px; /* someone's round mark */\n  --tempra-size-avatar-small: 20px; /* in a compact thread */\n  --tempra-size-avatar-menu: 26px; /* the avatar button that opens the account menu */\n  --tempra-size-avatar-large: 32px; /* at the head of the account menu */\n  --tempra-size-tile: 24px; /* a library's initial */\n  --tempra-size-tile-small: 20px; /* in a row: the sidebar, a menu, the bell */\n  --tempra-size-tile-large: 28px; /* the Tempra mark, a library card's cover */\n  --tempra-size-badge: 16px; /* the bell's count */\n  --tempra-size-dot: 6px; /* an agent's change, the agent replying */\n  --tempra-size-fab: 56px; /* a page's actions, floating */\n\n  /* Size: cards and dialogs */\n  --tempra-size-dialog: 32rem;\n  --tempra-size-dialog-wide: 40rem; /* a wide or compose dialog */\n  --tempra-size-media: 32rem; /* audio, a PDF's card and a broken figure in the full-screen view and on an attachment's page */\n  --tempra-size-menu: 13rem; /* a menu's least width */\n  --tempra-size-popover: 360px; /* the bell's panel */\n  --tempra-size-card: 240px; /* a library card's least width, the page's actions menu */\n  --tempra-size-tooltip: 22rem; /* a hover card */\n  --tempra-size-field: 22rem; /* a form field's widest */\n\n  /* Shape: squarer than take 2 */\n  --tempra-radius-code: 5px; /* code */\n  --tempra-radius-row: 7px; /* sidebar rows, inputs */\n  --tempra-radius-box: 10px; /* cards, list boxes, threads */\n  --tempra-radius-card: 10px; /* the public pages' sheet, dialogs */\n  --tempra-radius-tile: 6px; /* the library's initial */\n  --tempra-radius-pill: 999px;\n\n  /* Motion */\n  --tempra-motion-quick: 0.15s; /* a chevron or a + turning */\n  --tempra-motion-pulse: 1.6s; /* the change dot's pulse while an agent writes */\n  --tempra-motion-shimmer: 2s; /* one pass of the shimmer over a name an agent is at now (TEMPRA-219) */\n}\n\n/* The account's theme (take 4): the shell puts it on the root; the tokens above follow. */\n:root[data-theme=\"light\"] {\n  color-scheme: light;\n}\n\n:root[data-theme=\"dark\"] {\n  color-scheme: dark;\n}\n\n/* Element defaults for every page of the app and the site; values come from tokens.css. */\n*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  padding: var(--tempra-space-16);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-text);\n  font-size: var(--tempra-text-base);\n  line-height: var(--tempra-leading-base);\n  -webkit-font-smoothing: antialiased;\n}\n\n::selection {\n  background: var(--tempra-color-selection);\n}\n\nh1 {\n  font-family: var(--tempra-font-display);\n  font-variation-settings: var(--tempra-font-display-settings);\n  margin: 0 0 var(--tempra-space-16);\n  font-size: var(--tempra-text-page);\n  font-weight: var(--tempra-weight-medium);\n  line-height: var(--tempra-leading-tight);\n  letter-spacing: var(--tempra-tracking-title);\n}\n\nh2 {\n  margin: var(--tempra-space-32) 0 var(--tempra-space-08);\n  font-size: var(--tempra-text-base);\n  font-weight: var(--tempra-weight-strong);\n}\n\nh3 {\n  font-size: var(--tempra-text-ui);\n  font-weight: var(--tempra-weight-strong);\n}\n\na {\n  color: var(--tempra-color-link);\n  text-decoration: underline;\n  text-decoration-color: var(--tempra-color-border-strong);\n  text-underline-offset: var(--tempra-line-offset);\n}\n\na:visited {\n  color: var(--tempra-color-link-visited);\n}\n\na:hover {\n  text-decoration-color: currentcolor;\n}\n\n/* Focus (TEMPRA-132): the ring, 2px in the text colour, on every control reached by keyboard. */\n:focus-visible {\n  outline: var(--tempra-focus-ring);\n  outline-offset: var(--tempra-focus-offset);\n}\n\n/* A text field has the same ring, close to its edge. */\ninput:not([type=\"checkbox\"], [type=\"radio\"], [type=\"file\"]):focus-visible,\nselect:focus-visible,\ntextarea:focus-visible {\n  outline: var(--tempra-focus-ring);\n  outline-offset: var(--tempra-focus-offset-field);\n}\n\ncode,\npre,\nkbd,\nsamp {\n  font-family: var(--tempra-font-mono);\n}\n\ncode {\n  font-size: var(--tempra-text-code);\n}\n\n/* A block of code or a command never widens the page: it scrolls on its own. */\npre {\n  max-width: 100%;\n  overflow-x: auto;\n}\n\nkbd {\n  padding: var(--tempra-space-chip);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-muted);\n  font-family: inherit;\n  font-size: var(--tempra-text-label);\n}\n\nhr {\n  border: 0;\n  border-top: 1px solid var(--tempra-color-border);\n}\n\n/* Controls: pills. A plain button is outlined; .primary is the one solid action; .ghost is text.\n   A link that acts as a button (Review, Back to current) takes .button and looks the same. */\nbutton,\ninput,\nselect,\ntextarea {\n  font: inherit;\n  color: inherit;\n}\n\nbutton,\na.button {\n  padding: var(--tempra-space-button);\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-bg);\n  font-size: var(--tempra-text-ui);\n  white-space: nowrap;\n  cursor: pointer;\n}\n\na.button {\n  display: inline-block;\n  color: var(--tempra-color-text);\n  line-height: var(--tempra-leading-base);\n  text-decoration: none;\n}\n\nbutton:hover:not(:disabled),\na.button:hover {\n  background: var(--tempra-color-hover);\n  color: var(--tempra-color-text);\n}\n\nbutton:disabled {\n  cursor: default;\n  opacity: 0.5;\n}\n\nbutton.primary,\na.button.primary {\n  border-color: var(--tempra-color-text);\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n  font-weight: var(--tempra-weight-medium);\n}\n\nbutton.primary:hover:not(:disabled),\na.button.primary:hover {\n  background: var(--tempra-color-text);\n  opacity: 0.85;\n}\n\n/* A text-only button: a link's look, a button's job. */\nbutton.ghost {\n  border-color: transparent;\n  background: transparent;\n  color: var(--tempra-color-muted);\n}\n\ninput:not([type=\"checkbox\"], [type=\"radio\"], [type=\"file\"]),\nselect,\ntextarea {\n  max-width: 100%;\n  padding: var(--tempra-space-field);\n  border: 1px solid var(--tempra-color-border-strong);\n  border-radius: var(--tempra-radius-row);\n  background: var(--tempra-color-bg);\n  font-size: var(--tempra-text-ui);\n}\n\ntextarea {\n  line-height: var(--tempra-leading-base);\n}\n\nfieldset {\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n}\n\n/* A form as a column: a label over each field, choices on their own lines, actions last. */\nform.stack fieldset {\n  margin: 0 0 var(--tempra-space-20);\n  padding: 0;\n  border: 0;\n}\n\nform.stack legend {\n  margin-bottom: var(--tempra-space-06);\n  padding: 0;\n  font-weight: var(--tempra-weight-medium);\n}\n\n.field {\n  display: block;\n  margin: var(--tempra-space-10) 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.field input,\n.field select {\n  display: block;\n  width: 100%;\n  max-width: var(--tempra-size-field);\n  margin-top: var(--tempra-space-04);\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-base);\n}\n\n.choice {\n  display: flex;\n  align-items: baseline;\n  gap: var(--tempra-space-08);\n  margin: var(--tempra-space-04) 0;\n}\n\n.indent {\n  margin: var(--tempra-space-02) 0 var(--tempra-space-06) var(--tempra-space-24);\n}\n\n.actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: var(--tempra-space-08);\n  margin-top: var(--tempra-space-08);\n}\n\ntable {\n  border-collapse: collapse;\n}\n\nth,\ntd {\n  padding: var(--tempra-space-04) var(--tempra-space-08);\n  text-align: left;\n  vertical-align: top;\n}\n\nimg {\n  max-width: 100%;\n}\n\n/* An image whose size is known, until it loads: a quiet grey box at that size (TEMPRA-162). */\nimg.image-loading {\n  background: var(--tempra-color-ground);\n}\n\ndetails > summary {\n  cursor: pointer;\n}\n\n/* Text roles used across pages. */\n.muted {\n  color: var(--tempra-color-muted);\n}\n\n::placeholder {\n  color: var(--tempra-color-muted);\n  opacity: 1;\n}\n\n/* Who acted (AgentName, TEMPRA-131): the name, then whom an agent acts for, quieter. */\n.agent-name > b {\n  color: var(--tempra-color-text);\n  font-weight: var(--tempra-weight-medium);\n}\n\n.agent-for {\n  color: var(--tempra-color-muted);\n}\n\n.small {\n  font-size: var(--tempra-text-meta);\n}\n\n/* A form field's hint under it: what it becomes and the format it takes. */\n.field-hint {\n  display: block;\n  margin-top: var(--tempra-space-04);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.warn {\n  font-weight: var(--tempra-weight-medium);\n}\n\n/* An uppercase label over a group (SOURCES, LINKED FROM). */\n.label {\n  margin: 0 0 var(--tempra-space-08);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-label);\n  font-weight: var(--tempra-weight-regular);\n  letter-spacing: var(--tempra-tracking-label);\n  text-transform: uppercase;\n}\n\n/* A message about the page (saved, an error, a version in the past). */\n.notice {\n  margin: var(--tempra-space-08) 0;\n  padding: var(--tempra-space-10) var(--tempra-space-12);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  font-size: var(--tempra-text-ui);\n}\n\n.chip {\n  display: inline-block;\n  padding: var(--tempra-space-chip);\n  border: 1px solid transparent;\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-label);\n  white-space: nowrap;\n}\n\n/* Something to act on: in the text colour (no colour until the palette). */\n.chip.warn,\n.chip.bad {\n  color: var(--tempra-color-text);\n}\n\n/* Text for screen readers only: what a symbol (a mark, an icon) means. */\n.visually-hidden {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\n/*\n * How a rendered concept reads (tempra-dev: app/reader, Reading typography): the body of a\n * concept, in the app and in the page panel MCP `show` draws in a chat. Scoped to .prose. Inter's\n * text cut at the reading size (17px), about 66 characters to the line, spacing in em so the\n * rhythm scales with the text. Greys, type, spacing and rules only until the palette (TEMPRA-1).\n */\n.prose {\n  max-width: var(--tempra-measure-reader);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-text);\n  font-size: var(--tempra-text-reader);\n  line-height: var(--tempra-leading-reader);\n  font-kerning: normal;\n  font-optical-sizing: auto;\n  font-variant-ligatures: common-ligatures;\n  /* Lining figures in running text; tables and markers switch to tabular ones. */\n  font-variant-numeric: lining-nums proportional-nums;\n  /* Quotes and stops hang into the margin where the browser can (Safari). */\n  hanging-punctuation: first allow-end;\n  /* A long URL or identifier wraps rather than pushing the column wider; words never break. */\n  overflow-wrap: break-word;\n  hyphens: manual;\n  text-size-adjust: 100%;\n}\n\n.prose > :first-child,\n.prose > [hidden]:first-child + * {\n  margin-top: 0;\n}\n\n.prose > :last-child {\n  margin-bottom: 0;\n}\n\n/* Vertical rhythm: one step between blocks, in em. */\n.prose p,\n.prose ul,\n.prose ol,\n.prose blockquote,\n.prose pre,\n.prose .table {\n  margin: 0 0 1.1em;\n}\n\n/* No line ends on a lone short word; headings are balanced across their lines. */\n.prose p,\n.prose li,\n.prose blockquote {\n  text-wrap: pretty;\n}\n\n.prose strong {\n  font-weight: var(--tempra-weight-strong);\n}\n\n.prose s {\n  color: var(--tempra-color-muted);\n}\n\n/* Headings: more space above than below, so each sits with what it introduces. */\n.prose h1,\n.prose h2,\n.prose h3,\n.prose h4,\n.prose h5,\n.prose h6 {\n  margin: 1.9em 0 0.5em;\n  font-variant-numeric: lining-nums proportional-nums;\n  line-height: var(--tempra-leading-tight);\n  letter-spacing: -0.005em;\n  text-wrap: balance;\n  break-after: avoid;\n  /* Clear of the cluster when a contents link scrolls to it. */\n  scroll-margin-top: var(--tempra-space-72);\n}\n\n.prose h1 {\n  font-family: var(--tempra-font-display);\n  font-variation-settings: var(--tempra-font-display-settings);\n  font-size: 1.65em;\n  font-weight: var(--tempra-weight-medium);\n  letter-spacing: -0.012em;\n}\n\n.prose h2 {\n  font-family: var(--tempra-font-display);\n  font-variation-settings: var(--tempra-font-display-settings);\n  font-size: 1.35em;\n  font-weight: var(--tempra-weight-medium);\n  letter-spacing: -0.01em;\n}\n\n.prose h3 {\n  font-size: 1.12em;\n  font-weight: var(--tempra-weight-strong);\n}\n\n.prose h4,\n.prose h5,\n.prose h6 {\n  margin-top: 1.6em;\n  font-size: 1em;\n  font-weight: var(--tempra-weight-strong);\n  font-variant-caps: all-small-caps;\n  letter-spacing: 0.04em;\n}\n\n.prose h5,\n.prose h6 {\n  color: var(--tempra-color-muted);\n}\n\n/* A heading straight after another needs less room. */\n.prose :is(h1, h2, h3, h4, h5, h6) + :is(h2, h3, h4, h5, h6) {\n  margin-top: 0.7em;\n}\n\n/* Links: text-coloured, a thin underline at partial strength that firms up on hover. */\n.prose a {\n  color: inherit;\n  text-decoration-line: underline;\n  text-decoration-thickness: 1px;\n  text-decoration-color: color-mix(in srgb, currentColor 38%, transparent);\n  text-underline-offset: 0.18em;\n  text-decoration-skip-ink: auto;\n}\n\n.prose a:hover {\n  text-decoration-color: currentColor;\n}\n\n/* A link the reader would not follow (an unsafe scheme) reads as text. */\n.prose a:not([href]) {\n  text-decoration: none;\n}\n\n.prose a.broken {\n  color: var(--tempra-color-muted);\n  text-decoration-line: line-through;\n  text-decoration-color: currentColor;\n}\n\n/* Lists: muted markers, figures that line up; tight lists close, loose ones like paragraphs. */\n.prose ul,\n.prose ol {\n  padding-left: 1.4em;\n}\n\n.prose li {\n  margin: 0.2em 0;\n}\n\n.prose li::marker {\n  color: var(--tempra-color-muted);\n  font-variant-numeric: lining-nums tabular-nums;\n}\n\n.prose li > p {\n  margin: 0;\n}\n\n.prose li > :is(ul, ol) {\n  margin: 0.2em 0 0;\n}\n\n.prose :is(ul, ol).loose > li {\n  margin: 0.55em 0;\n}\n\n.prose :is(ul, ol).loose > li > p + * {\n  margin-top: 0.55em;\n}\n\n.prose .tasks {\n  padding-left: 0.1em;\n  list-style: none;\n}\n\n.prose li.task {\n  display: grid;\n  grid-template-columns: auto 1fr;\n  column-gap: 0.55em;\n  align-items: baseline;\n}\n\n.prose li.task > :not(input) {\n  grid-column: 2;\n}\n\n.prose li.task > input {\n  margin: 0;\n  accent-color: var(--tempra-color-text);\n}\n\n/* Blockquotes upright: long italic passages read slowly. */\n.prose blockquote {\n  margin-left: 0;\n  margin-right: 0;\n  padding: 0 0 0 1.1em;\n  border-left: 2px solid var(--tempra-color-border-strong);\n  color: var(--tempra-color-muted);\n}\n\n.prose blockquote > :last-child {\n  margin-bottom: 0;\n}\n\n/* Code: the mono a step down, no ligatures; inline on the code grey, blocks scroll sideways. */\n.prose code {\n  padding: 0.1em 0.35em;\n  border-radius: var(--tempra-radius-code);\n  background: var(--tempra-color-code-bg);\n  font-family: var(--tempra-font-mono);\n  font-size: 0.86em;\n  font-variant-ligatures: none;\n  font-variant-numeric: normal;\n  box-decoration-break: clone;\n  -webkit-box-decoration-break: clone;\n}\n\n.prose pre {\n  position: relative;\n  overflow-x: auto;\n  overscroll-behavior-x: contain;\n  padding: var(--tempra-space-14) var(--tempra-space-18);\n  border-radius: var(--tempra-radius-row);\n  background: var(--tempra-color-code-bg);\n  font-family: var(--tempra-font-mono);\n  font-size: 0.8em;\n  font-variant-ligatures: none;\n  line-height: var(--tempra-leading-base);\n  tab-size: 2;\n  white-space: pre;\n  overflow-wrap: normal;\n}\n\n.prose pre code {\n  padding: 0;\n  border-radius: 0;\n  background: none;\n  font-size: inherit;\n}\n\n/* The fence's language, quietly above the code (generated content: not part of the text). */\n.prose pre[data-lang] {\n  padding-top: var(--tempra-space-32);\n}\n\n.prose pre[data-lang]::before {\n  content: attr(data-lang);\n  position: absolute;\n  top: var(--tempra-space-10);\n  left: var(--tempra-space-18);\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-text);\n  font-size: var(--tempra-text-label);\n  letter-spacing: 0.04em;\n  text-transform: lowercase;\n}\n\n/* What the reader shows as its markdown (raw HTML, reference links): quieter than code. */\n.prose pre.raw,\n.prose code.raw {\n  color: var(--tempra-color-muted);\n}\n\n/*\n * Tables: real tables in their own scroll container, so a wide one scrolls sideways (on a phone\n * too) instead of breaking words. A table fills the column in a hairline box, with a light header\n * row on the ground grey and rules between rows, none between columns (take 3, Figures).\n */\n.prose .table {\n  max-width: 100%;\n  overflow-x: auto;\n  overscroll-behavior-x: contain;\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n}\n\n.prose table {\n  width: 100%;\n  border-collapse: collapse;\n  font-family: var(--tempra-font-text);\n  font-size: 0.82em;\n  font-variant-numeric: lining-nums tabular-nums;\n  line-height: var(--tempra-leading-base);\n}\n\n.prose th,\n.prose td {\n  padding: 0.6em 0.9em;\n  border: 0;\n  border-bottom: 1px solid var(--tempra-color-border);\n  text-align: left;\n  vertical-align: top;\n  overflow-wrap: normal;\n  word-break: normal;\n  text-wrap: pretty;\n}\n\n.prose tbody tr:last-child td {\n  border-bottom: 0;\n}\n\n.prose th {\n  background: var(--tempra-color-ground);\n  font-weight: var(--tempra-weight-medium);\n  vertical-align: bottom;\n}\n\n.prose td code,\n.prose th code {\n  background: none;\n  padding: 0;\n}\n\n.prose [data-align=\"center\"] {\n  text-align: center;\n}\n\n.prose [data-align=\"right\"] {\n  text-align: right;\n}\n\n.prose hr {\n  margin: 2.2em 0;\n  border: 0;\n  border-top: 1px solid var(--tempra-color-border);\n}\n\n/* An image in running text stays in the line, no taller than the column is wide. */\n.prose img {\n  max-width: 100%;\n  height: auto;\n  vertical-align: middle;\n}\n\n.prose .image-dropped,\n.prose .image-broken {\n  color: var(--tempra-color-muted);\n  font-style: italic;\n}\n\n.prose .image-broken {\n  padding: 0 0.3em;\n  border: 1px dashed var(--tempra-color-border-strong);\n  border-radius: var(--tempra-radius-code);\n}\n\n/*\n * Figures (take 3, Figures): an image alone in its paragraph, or a diagram, with a caption\n * beneath: \"Figure n.\" a step darker, then the image's title or alt text, in the UI face.\n */\n.prose figure {\n  margin: 1.6em 0;\n}\n\n.prose figure.figure > p {\n  margin: 0;\n}\n\n.prose .figure-media {\n  display: block;\n}\n\n.prose .figure-media img {\n  display: block;\n  max-width: 100%;\n  height: auto;\n  border-radius: var(--tempra-radius-box);\n}\n\n/*\n * Video, audio and PDF figures (TEMPRA-164; tempra-dev: app/media, How people see). A video\n * spans the column (its controls need the room), its stored width and height giving its shape,\n * with Enlarge in its corner;\n * audio is its controls across the text's column; a PDF is a card: a hairline box with its icon,\n * name, type and size, Open and Download as pills.\n */\n.prose .figure-video {\n  position: relative;\n}\n\n.prose .figure-media video {\n  display: block;\n  width: 100%;\n  height: auto;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n}\n\n.prose .figure-media audio {\n  display: block;\n  width: 100%;\n}\n\n.figure-pdf {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--tempra-space-12) var(--tempra-space-16);\n  padding: var(--tempra-space-16) var(--tempra-space-18);\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-text);\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-leading-base);\n}\n\n.figure-pdf > svg {\n  flex: none;\n  color: var(--tempra-color-faint);\n}\n\n.figure-pdf-about {\n  display: flex;\n  flex: 1 1 12rem; /* one-off: a PDF card's name, before its actions wrap */\n  flex-direction: column;\n  min-width: 0;\n}\n\n.figure-pdf-name {\n  font-weight: var(--tempra-weight-medium);\n  overflow-wrap: anywhere;\n}\n\n.figure-pdf-meta {\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.figure-pdf-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: var(--tempra-space-08);\n}\n\n.figure-pdf-actions a.button {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--tempra-space-06);\n  text-decoration: none;\n}\n\n/* The image is the button that enlarges it: no button look, a focus ring when reached by keys. */\n.prose .figure-open {\n  display: block;\n  max-width: 100%;\n  padding: 0;\n  border: 0;\n  border-radius: var(--tempra-radius-box);\n  background: none;\n  cursor: zoom-in;\n}\n\n.prose .figure-open:hover:not(:disabled) {\n  background: none;\n}\n\n.prose .figure-open:focus-visible {\n  outline: var(--tempra-focus-ring);\n  outline-offset: 3px; /* one-off: clear of the image's edge */\n}\n\n.prose figcaption {\n  margin-top: var(--tempra-space-08);\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-text);\n  font-size: var(--tempra-text-meta);\n  line-height: var(--tempra-leading-base);\n  text-wrap: pretty;\n  user-select: none;\n}\n\n.prose .figure-number {\n  color: var(--tempra-color-text);\n  font-weight: var(--tempra-weight-medium);\n}\n\n/* An external image's site, a quiet line under the caption (TEMPRA-163). */\n.prose .figure-source {\n  display: block;\n  color: var(--tempra-color-muted);\n}\n\n/*\n * Figure markup (TEMPRA-161; tempra-dev: app/media, Figure markup). Width: `--figure-width`, set on\n * the figure through the CSSOM, caps its images (max-width only, so an image is never drawn wider\n * than its own pixels). Placement, on a concept's page: wide and full reach past the text,\n * centred on the text's column (the page's width, 100cqi of `page`, less --concept-side; the\n * text is --doc-max wide at most with --doc-pad each side, concept.css), never past its padding;\n * wide stops at --tempra-figure-wide. Elsewhere they keep the text's width.\n */\n.prose figure.figure-sized:not(.figure-group) .figure-media,\n.prose figure.figure-sized:not(.figure-group) .figure-broken {\n  max-width: min(100%, var(--figure-width));\n}\n\n.prose figure.figure-group.figure-sized .figure-row {\n  max-width: min(100%, var(--figure-width));\n}\n\n.concept .prose figure.figure-wide {\n  --figure-reach: min(var(--tempra-size-figure-wide), var(--figure-column) - 2 * var(--doc-pad));\n}\n\n.concept .prose figure.figure-full {\n  --figure-reach: calc(var(--figure-column) - 2 * var(--doc-pad));\n}\n\n@container page (width >= 0px) {\n  .concept .prose figure:is(.figure-wide, .figure-full) {\n    --figure-column: calc(100cqi - var(--concept-side));\n    --figure-w: max(100%, var(--figure-reach));\n    width: var(--figure-w);\n    max-width: none;\n    margin-left: calc(\n      (min(var(--figure-column), var(--doc-max)) - var(--figure-w)) /\n      2 -\n      var(--doc-pad)\n    );\n  }\n}\n\n/* A frame for screenshots whose edges vanish on the page: a hairline, nothing more. */\n.prose figure.figure-framed .figure-media img {\n  border: 1px solid var(--tempra-color-border);\n}\n\n/* A group: its images side by side in equal columns, each with its title under it; stacked on a\n   phone. The newlines between them are text (they count) and are not drawn. */\n.prose .figure-row {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: var(--tempra-space-figure);\n  align-items: start;\n}\n\n.prose .figure-n-3 .figure-row {\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n}\n\n.prose .figure-n-4 .figure-row {\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n}\n\n.prose .figure-gap {\n  display: none;\n}\n\n.prose .figure-cell {\n  display: flex;\n  flex-direction: column;\n  gap: var(--tempra-space-06);\n  min-width: 0;\n}\n\n.prose .figure-label {\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-text);\n  font-size: var(--tempra-text-meta);\n  line-height: var(--tempra-leading-base);\n  user-select: none;\n}\n\n@media (max-width: 900px) {\n  .prose .figure-row,\n  .prose .figure-n-3 .figure-row,\n  .prose .figure-n-4 .figure-row {\n    grid-template-columns: minmax(0, 1fr);\n  }\n}\n\n/* A directive the reader does not draw: its opening and closing lines, quiet, as markdown. */\n.prose .directive > .raw-fence {\n  margin: 0.4em 0;\n  font-size: var(--tempra-text-meta);\n}\n\n/* An image that can't be shown: a dashed box where it would be, saying so, its path and alt. */\n.figure-broken {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: var(--tempra-space-04);\n  min-height: 12rem; /* one-off: a broken image's box */\n  padding: var(--tempra-space-24);\n  border: 1px dashed var(--tempra-color-border-strong);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-text);\n  font-size: var(--tempra-text-meta);\n  font-style: normal;\n  line-height: var(--tempra-leading-base);\n  text-align: center;\n  overflow-wrap: anywhere;\n}\n\n.figure-broken svg {\n  margin-bottom: var(--tempra-space-04);\n  color: var(--tempra-color-faint);\n}\n\n.figure-broken .figure-broken-title {\n  color: var(--tempra-color-text);\n  font-size: var(--tempra-text-ui);\n}\n\n/* Footnote markers: a source's number, small and muted, joined to its word. */\n.prose sup.fnref {\n  margin-left: 0.08em;\n  color: var(--tempra-color-muted);\n  font-size: 0.68em;\n  font-variant-numeric: lining-nums tabular-nums;\n  line-height: 0;\n  vertical-align: super;\n  white-space: nowrap;\n}\n\n.prose sup.fnref a {\n  padding: 0 0.12em;\n  color: inherit;\n  text-decoration: none;\n}\n\n.prose sup.fnref a:hover {\n  text-decoration: underline;\n}\n\n/* Changes in the text (review mode, a version chosen in History): insertions underlined on a\n   grey ground, deletions struck through in grey; the changed block's rule is concept.css's. */\n.prose ins.diff-added {\n  background: var(--tempra-color-ground);\n  text-decoration: underline;\n  text-decoration-thickness: 1px;\n  text-underline-offset: 0.22em;\n}\n\n.prose del.diff-removed {\n  color: var(--tempra-color-muted);\n  text-decoration: line-through;\n}\n\n/*\n * What sits around a concept body in the reader (tempra-dev: app/reader): the hover cards and the\n * selection toolbar (popovers in the top layer, placed by the app through --float-x and\n * --float-y), comment highlights (the CSS Custom Highlight API), diagrams and the full-screen\n * view of a figure. The threads are comments.css's, the Markdown view concept.css's. Lines and\n * greys only (no colour until TEMPRA-1).\n */\n\n/* A popover: placed at the coordinates the app gives it, never where the browser centres one. */\n.floating {\n  position: fixed;\n  inset: auto;\n  top: var(--float-y, 0);\n  left: var(--float-x, 0);\n  margin: 0;\n  padding: 0;\n  border: 0;\n  background: none;\n  color: inherit;\n  overflow: visible;\n}\n\n/* Hover cards over footnote markers and links. */\n.tooltip {\n  max-width: var(--tempra-size-tooltip);\n  padding: var(--tempra-space-08) var(--tempra-space-12);\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-text);\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-leading-base);\n  text-wrap: pretty;\n}\n\n.tooltip p {\n  margin: 0;\n}\n\n.tooltip p + p {\n  margin-top: 0.4em;\n}\n\n/*\n * Comments (TEMPRA-13, TEMPRA-223). An open thread's quote sits on a soft grey fill over a solid\n * mid-grey underline, so it reads as marked at a glance in light and dark (a 1px dotted underline\n * in the text colour read as nothing, and the hover grey as the page); the one whose thread is\n * active in the Comments panel takes a deeper fill and a 2px underline in ink; a comment being\n * written fills its text with the selection grey. Drawn as highlights, so the body's DOM never\n * changes for them.\n */\n::highlight(tempra-comment) {\n  background-color: var(--tempra-color-comment);\n  text-decoration-line: underline;\n  text-decoration-style: solid;\n  text-decoration-color: var(--tempra-color-comment-line);\n  text-decoration-thickness: 1.5px;\n  text-underline-offset: 0.2em;\n}\n\n::highlight(tempra-comment-active) {\n  background-color: var(--tempra-color-comment-active);\n  text-decoration-line: underline;\n  text-decoration-style: solid;\n  text-decoration-color: var(--tempra-color-text);\n  text-decoration-thickness: 2px;\n  text-underline-offset: 0.2em;\n}\n\n::highlight(tempra-comment-draft) {\n  background-color: var(--tempra-color-selection);\n}\n\n/* The selection toolbar: a pill above the selected text. */\n.selection-tools > div {\n  display: flex;\n  gap: var(--tempra-space-02);\n  padding: 3px; /* one-off: the pill's inset around its buttons */\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  font-family: var(--tempra-font-text);\n}\n\n.selection-tools button {\n  padding: var(--tempra-space-04) var(--tempra-space-12);\n  border: 0;\n  background: var(--tempra-color-text);\n  color: var(--tempra-color-bg);\n  font-size: var(--tempra-text-meta);\n  font-weight: var(--tempra-weight-medium);\n}\n\n.selection-tools button:hover:not(:disabled) {\n  background: var(--tempra-color-text);\n  opacity: 0.85;\n}\n\n/* A footnote's own text in the Sources section and a marker's card. */\n.note > p {\n  margin: 0;\n}\n\n.note > p + * {\n  margin-top: 0.4em;\n}\n\n/*\n * Diagrams (tempra-dev: app/diagrams): Pele's SVG themed through its custom properties, greys only\n * until the palette (TEMPRA-1), so dark mode follows the tokens. Colours an author sets in the\n * diagram are content and stay. In the body it sits in a quiet frame (take 3, Figures) with Source\n * and Enlarge in its corner, and scrolls sideways when it cannot shrink to the column; the\n * full-screen view draws it again with the same theme.\n */\n.prose figure.diagram,\n.lightbox {\n  --pele-bg: var(--tempra-color-bg);\n  --pele-fg: var(--tempra-color-text);\n  --pele-muted: var(--tempra-color-muted);\n  --pele-line: var(--tempra-color-muted);\n  --pele-surface: var(--tempra-color-ground);\n  --pele-surface-alt: var(--tempra-color-hover);\n  --pele-border: var(--tempra-color-border-strong);\n  --pele-accent: var(--tempra-color-text);\n  --pele-font: var(--tempra-font-text);\n  --pele-font-mono: var(--tempra-font-mono);\n  --pele-radius: var(--tempra-radius-row);\n  --pele-series-1: var(--tempra-color-text);\n  --pele-series-2: var(--tempra-color-muted);\n  --pele-series-3: var(--tempra-color-faint);\n  --pele-series-4: var(--tempra-color-border-strong);\n  --pele-series-5: var(--tempra-color-selection);\n  --pele-series-6: var(--tempra-color-selected);\n  --pele-series-7: var(--tempra-color-hover);\n  --pele-series-8: var(--tempra-color-ground);\n}\n\n.prose figure.diagram {\n  margin: 1.6em 0;\n}\n\n.prose .diagram-frame {\n  position: relative;\n  padding: var(--tempra-space-40) var(--tempra-space-20) var(--tempra-space-20);\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-box);\n}\n\n/* The font is set here, on the figure's container, not on the svg: an SVG fence's text with no\n   font-family of its own inherits the reader's Inter, and an author's font-family on the root or\n   on a text element still wins (TEMPRA-216). */\n.prose .diagram-svg {\n  overflow-x: auto;\n  overscroll-behavior-x: contain;\n  font-family: var(--tempra-font-text);\n  font-size: var(--tempra-text-ui);\n}\n\n.prose .diagram-svg svg {\n  display: block;\n  max-width: 100%;\n  height: auto;\n  margin: 0 auto;\n}\n\n.prose .diagram-frame pre.diagram-source {\n  margin: 0;\n}\n\n/* Source and Enlarge: small grey pills in the frame's corner. */\n.prose .figure-tools {\n  position: absolute;\n  top: var(--tempra-space-08);\n  right: var(--tempra-space-08);\n  display: flex;\n  gap: var(--tempra-space-02);\n  font-family: var(--tempra-font-text);\n}\n\n.prose .figure-tools button {\n  display: inline-grid;\n  place-items: center;\n  min-width: var(--tempra-size-control-mini);\n  height: var(--tempra-size-control-mini);\n  padding: 0 var(--tempra-space-10);\n  border: 0;\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-label);\n  line-height: 1;\n}\n\n.prose .figure-tools button:hover:not(:disabled),\n.prose .figure-tools button[aria-pressed=\"true\"] {\n  background: var(--tempra-color-hover);\n  color: var(--tempra-color-text);\n}\n\n.prose .figure-tools .figure-enlarge {\n  padding: 0;\n}\n\n.prose figure.diagram.failed pre {\n  margin: 0;\n}\n\n.prose .diagram-notice {\n  margin: var(--tempra-space-06) 0 0;\n  color: var(--tempra-color-muted);\n  font-family: var(--tempra-font-text);\n  font-size: var(--tempra-text-meta);\n}\n\n/* On a touch screen the corner controls are full-size targets. */\n@media (pointer: coarse) {\n  .prose .diagram-frame {\n    padding-top: 60px; /* one-off: room for the 44px tools above the diagram */\n  }\n\n  .prose .figure-tools {\n    top: var(--tempra-space-06);\n    right: var(--tempra-space-06);\n  }\n\n  .prose .figure-tools button {\n    min-width: var(--tempra-size-touch);\n    height: var(--tempra-size-touch);\n    font-size: var(--tempra-text-meta);\n  }\n}\n\n/*\n * The full-screen view of a figure (take 3, Lightbox): a modal dialog over the app on the ground\n * colour. A header (where, \"Figure n of m\", Open original and Download as pills, close), the\n * figure as large as fits between previous and next, and beneath it the caption and a quiet line.\n */\n.lightbox {\n  position: fixed;\n  inset: 0;\n  width: 100%;\n  max-width: none;\n  height: 100%;\n  max-height: none;\n  margin: 0;\n  padding: 0;\n  border: 0;\n  background: var(--tempra-color-ground);\n  color: var(--tempra-color-text);\n  font-family: var(--tempra-font-text);\n  font-size: var(--tempra-text-ui);\n  line-height: var(--tempra-leading-base);\n  overflow: hidden;\n}\n\n.lightbox[open] {\n  display: grid;\n  grid-template-rows: auto minmax(0, 1fr) auto;\n}\n\n.lightbox::backdrop {\n  background: var(--tempra-color-ground);\n}\n\n.lightbox-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--tempra-space-08) var(--tempra-space-12);\n  padding: var(--tempra-space-16) var(--tempra-space-20);\n}\n\n.lightbox-where {\n  color: var(--tempra-color-muted);\n}\n\n.lightbox-where::after {\n  content: \"·\";\n  margin-left: var(--tempra-space-12);\n  color: var(--tempra-color-faint);\n}\n\n.lightbox-actions {\n  display: flex;\n  gap: var(--tempra-space-06);\n  margin-left: auto;\n}\n\n.lightbox-actions a {\n  display: inline-flex;\n  align-items: center;\n  padding: var(--tempra-space-06) var(--tempra-space-14);\n  border: 1px solid var(--tempra-color-border);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--tempra-color-bg);\n  color: var(--tempra-color-text);\n  text-decoration: none;\n  white-space: nowrap;\n}\n\n.lightbox-actions a:hover {\n  background: var(--tempra-color-hover);\n}\n\n.lightbox-round {\n  display: inline-grid;\n  flex: none;\n  place-items: center;\n  width: 34px; /* one-off: the full-screen view's close */\n  height: 34px;\n  padding: 0;\n  border: 1px solid var(--tempra-color-border);\n  background: var(--tempra-color-bg);\n}\n\n.lightbox-stage {\n  display: grid;\n  grid-template-columns: auto minmax(0, 1fr) auto;\n  align-items: center;\n  gap: var(--tempra-space-16);\n  min-height: 0;\n  padding: 0 var(--tempra-space-20);\n}\n\n.lightbox-stage .lightbox-prev,\n.lightbox-stage .lightbox-next {\n  width: var(--tempra-size-touch);\n  height: var(--tempra-size-touch);\n}\n\n.lightbox-prev {\n  grid-column: 1;\n}\n\n.lightbox-figure {\n  display: grid;\n  grid-column: 2;\n  place-items: center;\n  width: 100%;\n  height: 100%;\n  min-height: 0;\n}\n\n.lightbox-next {\n  grid-column: 3;\n}\n\n/* Its natural size within the stage (the width and height attributes only give its candidates'\n   proportions; nothing is beside it to move). */\n.lightbox-figure > img {\n  display: block;\n  width: auto;\n  height: auto;\n  max-width: 100%;\n  max-height: 100%;\n  object-fit: contain;\n  border-radius: var(--tempra-radius-card);\n  box-shadow: var(--tempra-shadow);\n}\n\n/* A video plays as large as fits; audio and a PDF's card sit in the middle (TEMPRA-164). */\n.lightbox-figure > video {\n  display: block;\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n}\n\n.lightbox-figure > audio {\n  width: min(100%, var(--tempra-size-media));\n}\n\n.lightbox-figure > .figure-pdf {\n  width: min(100%, var(--tempra-size-media));\n  box-shadow: var(--tempra-shadow);\n}\n\n.lightbox-figure > .figure-broken {\n  width: min(100%, var(--tempra-size-media));\n}\n\n.lightbox-diagram {\n  box-sizing: border-box;\n  width: 100%;\n  height: 100%;\n  padding: var(--tempra-space-24);\n  border-radius: var(--tempra-radius-card);\n  background: var(--tempra-color-bg);\n  box-shadow: var(--tempra-shadow);\n  font-family: var(--tempra-font-text);\n  font-size: var(--tempra-text-ui);\n}\n\n.lightbox-diagram svg {\n  display: block;\n  width: 100%;\n  height: 100%;\n}\n\n.lightbox-source {\n  max-width: 100%;\n  max-height: 100%;\n  margin: 0;\n  padding: var(--tempra-space-16) var(--tempra-space-18);\n  overflow: auto;\n  border-radius: var(--tempra-radius-box);\n  background: var(--tempra-color-bg);\n  font-family: var(--tempra-font-mono);\n  font-size: var(--tempra-text-ui);\n}\n\n.lightbox-foot {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: var(--tempra-space-04);\n  padding: var(--tempra-space-18) var(--tempra-space-20) 26px; /* one-off: the caption's foot */\n  text-align: center;\n}\n\n.lightbox-caption {\n  max-width: var(--tempra-measure);\n  margin: 0;\n  font-size: var(--tempra-text-name);\n  text-wrap: pretty;\n}\n\n.lightbox-facts {\n  max-width: var(--tempra-measure);\n  margin: 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n  overflow-wrap: anywhere;\n}\n\n.lightbox-facts > span + span::before {\n  content: \" · \";\n}\n\n/* A phone: smaller gutters, 44px targets, no keyboard hint. */\n@media (max-width: 600px) {\n  .lightbox-head {\n    padding: var(--tempra-space-08) var(--tempra-space-12);\n  }\n\n  .lightbox-where {\n    display: none;\n  }\n\n  .lightbox-actions a {\n    min-height: var(--tempra-size-touch);\n    padding: 0 var(--tempra-space-14);\n  }\n\n  .lightbox-round {\n    width: var(--tempra-size-touch);\n    height: var(--tempra-size-touch);\n  }\n\n  .lightbox-stage {\n    gap: var(--tempra-space-04);\n    padding: 0 var(--tempra-space-04);\n  }\n\n  .lightbox-foot {\n    padding: var(--tempra-space-12) var(--tempra-space-16) var(--tempra-space-20);\n  }\n\n  .lightbox-hint {\n    display: none;\n  }\n}\n\n/*\n * Panels: the views an MCP host draws in a chat (TEMPRA-200, the upload panel; tempra-dev\n * app/media, Upload panel). Not part of tempra.css: build.ts puts tokens.css and this file into\n * dist/panel.ts, which the app's build inlines into each panel's one HTML document. A panel sits\n * in the host's conversation, so it takes the host's theme variables (SEP-1865, Theming) where\n * the host gives them, and Tempra's greys where it does not. No webfont: the host's sans, else\n * the system's.\n */\n\n:root {\n  color-scheme: light dark;\n}\n\n:root[data-theme=\"light\"] {\n  color-scheme: light;\n}\n\n:root[data-theme=\"dark\"] {\n  color-scheme: dark;\n}\n\n.panel {\n  --panel-text: var(--color-text-primary, var(--tempra-color-text));\n  --panel-muted: var(--color-text-secondary, var(--tempra-color-muted));\n  --panel-surface: var(--color-background-primary, var(--tempra-color-bg));\n  --panel-inset: var(--color-background-secondary, var(--tempra-color-ground));\n  --panel-border: var(--color-border-primary, var(--tempra-color-border-strong));\n  --panel-radius: var(--border-radius-lg, var(--tempra-radius-box));\n  margin: 0;\n  padding: var(--tempra-space-16);\n  background: var(--panel-surface);\n  color: var(--panel-text);\n  font-family: var(--font-sans, system-ui, -apple-system, \"Segoe UI\", sans-serif);\n  font-size: var(--tempra-text-base);\n  line-height: 1.45; /* the hosts' own leading, a little tighter than the app's */\n}\n\n.panel h1 {\n  margin: 0 0 var(--tempra-space-04);\n  font-size: var(--tempra-text-name);\n  font-weight: var(--tempra-weight-strong);\n}\n\n.panel p {\n  margin: 0 0 var(--tempra-space-08);\n}\n\n.panel .muted {\n  color: var(--panel-muted);\n}\n\n.panel code {\n  font-family: var(--font-mono, ui-monospace, \"SF Mono\", Menlo, monospace);\n  font-size: var(--tempra-text-code);\n  overflow-wrap: anywhere;\n}\n\n/* The drop area: the file input's label, a dashed box that says what to do. */\n.panel .drop {\n  display: block;\n  margin: var(--tempra-space-12) 0 var(--tempra-space-08);\n  padding: var(--tempra-space-20) var(--tempra-space-16);\n  border: 1.5px dashed var(--panel-border); /* one-off: the drop area's edge */\n  border-radius: var(--panel-radius);\n  background: var(--panel-inset);\n  text-align: center;\n  cursor: pointer;\n}\n\n/* Gone once the file is in: `hidden` over the display rule above. */\n.panel .drop[hidden] {\n  display: none;\n}\n\n.panel .drop .hint {\n  display: block;\n  margin-top: var(--tempra-space-04);\n}\n\n.panel .drop.over {\n  border-style: solid;\n  border-color: var(--panel-text);\n}\n\n.panel .drop:focus-within {\n  outline: 2px solid var(--panel-text); /* the focus ring, in the host's text colour */\n  outline-offset: var(--tempra-focus-offset);\n}\n\n/* The input stays in the label for the keyboard and screen readers, out of sight. */\n.panel .drop input {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\n.panel .status {\n  min-height: 1.45em;\n  margin: var(--tempra-space-08) 0 0;\n}\n\n.panel .actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: var(--tempra-space-08);\n  align-items: center;\n  margin-top: var(--tempra-space-08);\n}\n\n.panel button {\n  padding: var(--tempra-space-06) var(--tempra-space-14);\n  border: 1px solid var(--panel-border);\n  border-radius: var(--tempra-radius-pill);\n  background: var(--panel-surface);\n  color: var(--panel-text);\n  font: inherit;\n  cursor: pointer;\n}\n\n.panel button.primary {\n  border-color: var(--panel-text);\n  background: var(--panel-text);\n  color: var(--panel-surface);\n}\n\n.panel button:disabled {\n  cursor: default;\n}\n\n.panel button:focus-visible {\n  outline: 2px solid var(--panel-text); /* the focus ring, in the host's text colour */\n  outline-offset: var(--tempra-focus-offset);\n}\n\n.panel progress {\n  width: 100%;\n  height: 6px; /* one-off: the progress bar */\n  margin-top: var(--tempra-space-08);\n}\n\n/* ---------- The page panel (tempra-dev app/page-panel): one page shown in the chat by `show` ----------\n * Unlike the upload panel it reads as Tempra does, not as the host: Inter, the reader's prose and\n * the base pills. Its stylesheet is fonts, tokens, base, prose, reader and this file (build.ts,\n * dist/panel.ts `pagePanelCss`); the host's light or dark comes in as data-theme. */\n\n.page-body {\n  margin: 0;\n  padding: var(--tempra-space-20) var(--tempra-space-20) var(--tempra-space-24);\n  background: var(--tempra-color-bg);\n}\n\n.page-panel .pp-head {\n  margin-bottom: var(--tempra-space-24);\n}\n\n.page-panel .pp-where {\n  margin: 0 0 var(--tempra-space-12);\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-meta);\n}\n\n.page-panel .pp-title {\n  margin: 0 0 var(--tempra-space-08);\n  font-family: var(--tempra-font-display);\n  font-variation-settings: var(--tempra-font-display-settings);\n  font-size: var(--tempra-text-page);\n  font-weight: var(--tempra-weight-medium);\n  line-height: var(--tempra-leading-tight);\n  letter-spacing: var(--tempra-tracking-doc);\n}\n\n.page-panel .pp-description {\n  margin: 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-reader);\n}\n\n.page-panel .pp-byline {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--tempra-space-06) var(--tempra-space-08);\n  margin: var(--tempra-space-12) 0 0;\n  color: var(--tempra-color-muted);\n  font-size: var(--tempra-text-ui);\n}\n\n.page-panel .prose {\n  max-width: var(--tempra-measure-reader);\n}\n\n.page-panel .pp-sources {\n  margin-top: 2em;\n  padding-top: 1em;\n  border-top: 1px solid var(--tempra-color-border);\n}\n\n.page-panel .pp-sources h2 {\n  margin-top: 0;\n}\n";
